"""Conformance test files: expected results, generated by this library, for ports to other languages.

An app that re-implements part of pakgrid in its own language (for example live
navigation in Dart, inside a Flutter app) runs its port against these files.
If it gives the same answers for every case, it matches pakgrid.

    pakgrid export-conformance -o conformance

writes conformance/navigation.json. The rules it tests are written out in
conformance/NAVIGATION.md.

Random cases are chosen so that none lies within MARGIN of a decision
threshold (a compass sector boundary, a turn-word limit, the arrival distance,
the GPS jump test, ...). Last-digit differences in sin/cos between platforms
therefore cannot change a word or a status, and numbers can be compared with
the small tolerances in the file. Exact ties are tested separately, with
inputs that need no trigonometry (compass bearings, turn angles, distances).
"""

import json
import math
import random

from . import __version__, geodesy, spec
from .navigate import _COMPASS_8, _COMPASS_16, NavigationSession, direction, format_distance, turn_words

FORMAT_VERSION = 1
MARGIN = 1e-6           # metres or degrees between a random case and any decision threshold
TOLERANCE = {
    "metres": 1e-6,     # distance_m, distance_ft, lat_m / lon_m per degree
    "degrees": 1e-9,    # bearings, turns, headings, arrow rotation
    "coordinates": 1e-12,   # lat, lon (degrees)
}

# Which tolerance applies to each numeric result field; every other field must match exactly.
FIELD_TOLERANCE = {
    "distance_m": "metres", "distance_ft": "metres", "accuracy_m": "metres", "lat_m": "metres", "lon_m": "metres",
    "bearing_deg": "degrees", "turn_deg": "degrees", "heading_deg": "degrees", "arrow_deg": "degrees",
    "lat": "coordinates", "lon": "coordinates", "target_lat": "coordinates", "target_lon": "coordinates",
}

_TURN_LIMITS = (10.0, 30.0, 60.0, 135.0, 180.0)


class _TooClose(Exception):
    pass


def _check(value, threshold):
    if abs(value - threshold) < MARGIN:
        raise _TooClose


def _check_bearing(brg):
    # sector boundaries of the 16-point names (the 8-point boundaries are among them)
    for k in range(16):
        _check(brg, 11.25 + 22.5 * k)
    # just either side of north, a tiny difference could give 359.999... instead of 0.000...;
    # exactly 0 (no east-west difference at all) is the same everywhere
    if brg != 0.0 and (brg < MARGIN or brg > 360.0 - MARGIN):
        raise _TooClose


def _check_turn(turn_deg):
    for limit in _TURN_LIMITS:
        _check(abs(turn_deg), limit)


def _check_state(nav, s):
    if s.status == "waiting":
        return
    _check(s.distance_m, nav.arrived_m)
    _check(s.distance_m, nav.almost_m)
    _check_bearing(s.bearing_deg)
    if s.turn_deg is not None:
        _check_turn(s.turn_deg)


# -- Building blocks -------------------------------------------------------------

def _compass_cases():
    bearings = [k * 11.25 for k in range(32)] + [0.0, 359.99, 360.0 - 1e-9, 5.625, 348.75, 337.5]
    return [{"bearing_deg": b, "compass": _COMPASS_8[round(b / 45.0) % 8],
             "compass_short": _COMPASS_16[round(b / 22.5) % 16]} for b in bearings]


def _turn_cases():
    angles = [0.0, 9.99, 10.0, -10.0, 29.99, 30.0, -30.0, 59.99, 60.0, -60.0, 134.99, 135.0, -135.0,
              179.9, -180.0, 45.0, -45.0, 90.0, -90.0, 5.0, -5.0]
    return [{"turn_deg": t, "turn": turn_words(t)} for t in angles]


def _distance_cases():
    metres = [0.0, 2.4, 2.5, 7.5, 12.5, 17.5, 97.4, 97.5, 99.99, 100.0, 104.99, 105.0, 115.0, 125.0,
              434.0, 995.0, 999.9, 1000.0, 1049.9, 1050.0, 1150.0, 1250.0, 12345.6, 150000.0]
    feet_as_metres = [ft * 0.3048 for ft in (0.0, 12.5, 17.5, 297.4, 297.5, 300.0, 305.0, 315.0,
                                             5275.0, 5280.0, 5544.0, 5808.0, 52800.0)]
    out = []
    for m in metres + feet_as_metres:
        for units in ("m", "ft"):
            out.append({"metres": m, "units": units, "text": format_distance(m, units)})
    return out


def _scale_cases():
    out = []
    for lat in (23.5, 24.86, 27.0, 30.258, 31.5204, 33.68, 35.3, 37.08):
        m_lat, m_lon = geodesy.metres_per_degree(lat)
        out.append({"lat": lat, "lat_m": m_lat, "lon_m": m_lon})
    return out


def _direction_cases(rng, n):
    out = []
    fixed = [(31.5215, 74.3570, 31.5204, 74.3587, 90.0), (31.52085, 74.35855, 31.5204, 74.3587, 180.0),
             (31.5204, 74.3587, 31.5204, 74.3587, None), (31.5, 74.3, 31.6, 74.3001, 350.0),
             (24.86, 67.0, 24.87, 67.0, None), (35.3, 75.6, 35.29, 75.61, 10.0)]
    while len(fixed) + len(out) < n:
        lat, lon = rng.uniform(23.6, 37.0), rng.uniform(61.0, 77.8)
        case = (lat, lon, lat + rng.uniform(-0.05, 0.05), lon + rng.uniform(-0.05, 0.05),
                rng.choice([None, rng.uniform(-30.0, 400.0)]))
        d = direction(*case)
        try:
            _check_bearing(d.bearing_deg)
            if d.turn_deg is not None:
                _check_turn(d.turn_deg)
        except _TooClose:
            continue
        out.append(case)
    cases = []
    for c in fixed + out:
        d = direction(*c)
        cases.append({"from": [c[0], c[1]], "to": [c[2], c[3]], "heading": c[4],
                      "expected": {k: v for k, v in d.__dict__.items()}})
    return cases


# -- Navigation sessions -----------------------------------------------------------

def _run(target, options, steps):
    """Play steps through a NavigationSession, recording the expected state after each.

    Raises _TooClose if any decision in the run lies within MARGIN of its threshold.
    """
    nav = NavigationSession(*target, **options)
    out = []
    for call, args in steps:
        # every argument is written out, null when not given, so ports can rely on the keys
        args = {**{k: None for k in _ARGS[call]}, **args}
        # decisions taken inside the call, checked before making it
        if call == "add_fix" and nav._live:
            acc = max(args.get("accuracy") or 20.0, 1.0)
            _check(direction(*nav.position, args["lat"], args["lon"]).distance_m, max(acc, 5.0))
        if call == "set_position" and nav._anchor is not None and args.get("heading") is None:
            _check(direction(*nav._anchor, args["lat"], args["lon"]).distance_m, 2.0)
        if call == "add_fix":
            s = nav.add_fix(args["lat"], args["lon"], accuracy=args.get("accuracy"), speed=args.get("speed"),
                            heading=args.get("heading"), time=args["time"])
        elif call == "add_compass":
            s = nav.add_compass(args["heading"], time=args["time"])
        elif call == "set_position":
            s = nav.set_position(args["lat"], args["lon"], heading=args.get("heading"))
        elif call == "set_target":
            s = nav.set_target(args["lat"], args["lon"])
        elif call == "reset":
            s = nav.reset()
        else:
            raise ValueError(call)
        _check_state(nav, s)
        out.append({"call": call, "args": args, "expect": s.to_dict()})
    return out


_ARGS = {
    "add_fix": ("lat", "lon", "accuracy", "speed", "heading", "time"),
    "add_compass": ("heading", "time"),
    "set_position": ("lat", "lon", "heading"),
    "set_target": ("lat", "lon"),
    "reset": (),
}


def _at(origin, east, north):
    lat, lon = geodesy.apply_offset(*origin, east, north)
    return {"lat": lat, "lon": lon}


def _named_sessions():
    t = (31.5204, 74.3587)

    def fix(e, n, time, **kw):
        return ("add_fix", {**_at(t, e, n), "time": time, **kw})

    def pos(e, n, **kw):
        return ("set_position", {**_at(t, e, n), **kw})

    return [
        ("waiting, then first fix (north-up arrow)", t, {}, [
            ("reset", {}), fix(-300, -400, 0.0, accuracy=5.0)]),
        ("jitter within accuracy is averaged; a 100 m jump starts afresh", t, {}, [
            fix(0, -500, 0.0, accuracy=10.0), fix(4, -500, 1.0, accuracy=10.0),
            fix(2, -499, 2.0, accuracy=10.0), fix(0, -400, 3.0, accuracy=10.0)]),
        ("accuracy weighting: 1 / accuracy squared", t, {}, [
            fix(0, -500, 0.0, accuracy=4.0), fix(3, -500, 1.0, accuracy=8.0)]),
        ("missing or zero accuracy counts as 20 m", t, {}, [
            fix(0, -500, 0.0), fix(6, -500, 1.0, accuracy=0.0), fix(3, -498, 2.0, accuracy=20.0)]),
        ("only the last 3 readings, each under 10 s old, are averaged", t, {}, [
            fix(0, -500, 0.0, accuracy=10.0), fix(1, -500, 1.0, accuracy=10.0), fix(2, -500, 2.0, accuracy=10.0),
            fix(3, -500, 3.0, accuracy=10.0), fix(4, -500, 12.0, accuracy=10.0),     # 12 - 2 = 10 s: too old
            fix(5, -500, 30.0, accuracy=10.0)]),
        ("GPS course is used when moving at 2 m/s or more", t, {}, [
            ("add_compass", {"heading": 10.0, "time": 0.0}), fix(0, -500, 0.5, accuracy=5.0, speed=6.0, heading=90.0),
            ("add_compass", {"heading": 20.0, "time": 1.0}),
            fix(0, -480, 1.5, accuracy=5.0, speed=2.0, heading=375.0),
            fix(0, -470, 2.0, accuracy=5.0, speed=1.99, heading=45.0)]),
        ("compass when slow, only while fresh (under 3 s)", t, {}, [
            ("add_compass", {"heading": 375.0, "time": 0.0}), fix(-30, -500, 1.0, speed=0.5, heading=90.0),
            ("add_compass", {"heading": -15.0, "time": 2.0}), fix(-30, -500, 4.9, speed=0.0),
            fix(-30, -500, 5.0, speed=0.0), ("add_compass", {"heading": float("nan"), "time": 5.5})]),
        ("a compass reading taken before the first fix is used once a fix arrives, if fresh", t, {}, [
            ("add_compass", {"heading": 200.0, "time": 0.0}), fix(0, -500, 1.0)]),
        ("set_position: heading from movement of 2 m or more", t, {}, [
            pos(0, -500), pos(1, -500), pos(0, -490), pos(0.5, -490), pos(10, -480), pos(0, -470, heading=200.0),
            ("add_compass", {"heading": 300.0, "time": 0.0})]),
        ("arrival: almost under 50 m, arrived under 15 m", t, {}, [
            pos(0, -60), pos(0, -40), pos(0, -10), pos(0, 0)]),
        ("turn words and arrow relative to the heading", t, {}, [
            pos(0, -500, heading=0.0), pos(0, -500, heading=20.0), pos(0, -500, heading=45.0),
            pos(0, -500, heading=90.0), pos(0, -500, heading=200.0), pos(0, -500, heading=-40.0)]),
        ("set_target keeps the rider; reset forgets the rider but not the compass", t, {}, [
            fix(0, -500, 0.0), ("set_target", _at(t, 0, -1000)), ("add_compass", {"heading": 90.0, "time": 1.0}),
            ("reset", {}), fix(0, -500, 2.0)]),
        ("custom thresholds", t, {"arrived_m": 5.0, "almost_m": 100.0, "moving_mps": 5.0, "compass_fresh_s": 1.0,
                                  "smoothing_window_s": 3.0, "smoothing_count": 2}, [
            fix(0, -80, 0.0, accuracy=10.0, speed=4.0, heading=0.0), fix(2, -80, 1.0, accuracy=10.0, speed=5.0,
                                                                        heading=0.0),
            fix(1, -81, 2.0, accuracy=10.0), fix(1, -80, 4.5, accuracy=10.0), pos(0, -4)]),
    ]


def _random_steps(rng, target):
    lat, lon, t = target[0] + rng.uniform(-0.01, 0.01), target[1] + rng.uniform(-0.01, 0.01), 0.0
    steps = []
    for _ in range(60):
        t = round(t + rng.choice([0.2, 1.0, 1.0, 1.0, 2.5, 4.0, 12.0]), 6)
        kind = rng.choices(["add_fix", "add_compass", "set_position", "set_target", "reset"], [60, 20, 15, 3, 2])[0]
        lat += rng.uniform(-3e-4, 3e-4)
        lon += rng.uniform(-3e-4, 3e-4)
        if kind == "add_fix":
            steps.append(("add_fix", {"lat": lat, "lon": lon, "accuracy": rng.choice([None, 0.0, 3.0, 8.0, 25.0, 60.0]),
                                      "speed": rng.choice([None, 0.5, 2.0, 7.0]),
                                      "heading": rng.choice([None, rng.uniform(-30.0, 400.0)]), "time": t}))
        elif kind == "add_compass":
            steps.append(("add_compass", {"heading": rng.choice([rng.uniform(0.0, 360.0), 360.0, -15.0]), "time": t}))
        elif kind == "set_position":
            steps.append(("set_position", {"lat": lat, "lon": lon,
                                           "heading": rng.choice([None, None, rng.uniform(0.0, 360.0)])}))
        elif kind == "set_target":
            steps.append(("set_target", {"lat": lat + rng.uniform(-0.002, 0.002), "lon": lon + rng.uniform(-0.002, 0.002)}))
        else:
            steps.append(("reset", {}))
    return steps


def _sessions(rng, n_random):
    out = []
    for name, target, options, steps in _named_sessions():
        try:
            run = _run(target, options, steps)
        except _TooClose:
            raise ValueError(f"named session {name!r} has a decision too close to its threshold") from None
        out.append({"name": name, "target": list(target), "options": options, "steps": run})
    while len(out) < len(_named_sessions()) + n_random:
        r = random.Random(rng.random())
        target = (r.uniform(23.6, 37.0), r.uniform(61.0, 77.8))
        try:
            steps = _run(target, {}, _random_steps(r, target))
        except _TooClose:
            continue
        out.append({"name": f"random ride {len(out) - len(_named_sessions()) + 1}", "target": list(target),
                    "options": {}, "steps": steps})
    return out


# -- The file ------------------------------------------------------------------------

def navigation_suite(n_direction=300, n_random_sessions=25, seed=2026):
    rng = random.Random(seed)
    return {
        "format": "pakgrid-conformance",
        "suite": "navigation",
        "format_version": FORMAT_VERSION,
        "grid_version": spec.GRID_VERSION,
        "generated_by": f"pakgrid {__version__}",
        "rules": "conformance/NAVIGATION.md",
        "tolerance": TOLERANCE,
        "field_tolerance": FIELD_TOLERANCE,
        "compass": _compass_cases(),
        "turn_words": _turn_cases(),
        "format_distance": _distance_cases(),
        "metres_per_degree": _scale_cases(),
        "direction": _direction_cases(rng, n_direction),
        "sessions": _sessions(rng, n_random_sessions),
    }


def navigation_json():
    """The navigation suite as JSON text. NaN inputs are written as the string "NaN"."""
    def clean(o):
        if isinstance(o, dict):
            return {k: clean(v) for k, v in o.items()}
        if isinstance(o, list):
            return [clean(v) for v in o]
        if isinstance(o, float) and math.isnan(o):
            return "NaN"
        return o
    return json.dumps(clean(navigation_suite()), indent=1, allow_nan=False) + "\n"


def write_conformance_files(output_dir="conformance"):
    from pathlib import Path
    out = Path(output_dir)
    out.mkdir(parents=True, exist_ok=True)
    path = out / "navigation.json"
    path.write_text(navigation_json(), encoding="utf-8", newline="\n")
    return [path]
